import os
from functools import wraps
from flask import Flask, send_file, jsonify, abort

app = Flask(__name__)

def route_with_image_check(url):
    def decorator(f):
        @wraps(f)
        def wrapper(*args, **kwargs):
            try:
                # Llamar a la función original para obtener el nombre del archivo
                filename = f(*args, **kwargs)
                image_path = os.path.join('static/images', filename)

                # Verificar si el archivo existe
                if os.path.exists(image_path):
                    return send_file(image_path)
                else:
                    return jsonify({"error": "Imagen no encontrada"}), 404
            except Exception as e:
                print(f"Error: {e}")
                return jsonify({"error": "Error interno del servidor"}), 500
        # Registrar la ruta en Flask
        app.add_url_rule(url, f.__name__, wrapper)
        return wrapper
    return decorator

# Ejemplo de uso del decorador
@route_with_image_check('/image/<filename>')
def get_image(filename):
    return filename

# Ejemplo de ruta para probar el error
@app.route('/error')
def error_route():
    raise Exception("Simulación de error")

if __name__ == '__main__':
    app.run(debug=True)

